def __getitem__(self, item):
    if isinstance(item, slice):
        # Slice access - return tuple for slices
        return self.fixed[item]
    elif isinstance(item, int):
        return self.fixed[item]
    return self.named[item]

def __contains__(self, item):
    '''Check if item is in fixed values or named values.'''
    if item in self.fixed:
        return True
    if item in self.named:
        return True
    # Also check if item is a key in nested dicts within named
    for v in self.named.values():
        if isinstance(v, dict) and item in v:
            return True
    return False

